package com.asmj.marketplace.controller;
import com.asmj.marketplace.engagement.*; import com.asmj.marketplace.model.*; import com.asmj.marketplace.repository.UserAccountRepository; import jakarta.servlet.http.HttpSession; import java.math.BigDecimal; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class CouponController {
 private final CouponRepository coupons; private final UserAccountRepository users;
 public CouponController(CouponRepository c,UserAccountRepository u){coupons=c;users=u;}
 @GetMapping("/customer/offers") public String offers(Model m){m.addAttribute("coupons",coupons.findAllByOrderByCreatedAtDesc().stream().filter(c->c.isActive()&&(c.getStartsAt()==null||!c.getStartsAt().isAfter(Instant.now()))&&(c.getEndsAt()==null||!c.getEndsAt().isBefore(Instant.now()))&&(c.getUsageLimit()==null||c.getUsageCount()<c.getUsageLimit())).toList());return "customer/offers";}
 @GetMapping("/admin/coupons") public String admin(Model m){m.addAttribute("coupons",coupons.findAllByOrderByCreatedAtDesc());return "admin/coupons";}
 @PostMapping("/admin/coupons") public String create(@RequestParam String code,@RequestParam String description,@RequestParam DiscountCoupon.DiscountType discountType,@RequestParam BigDecimal value,@RequestParam(defaultValue="0") BigDecimal minimumOrder,@RequestParam(required=false) BigDecimal maximumDiscount,@RequestParam(required=false) Integer usageLimit,RedirectAttributes ra){String normalized=code==null?"":code.trim().toUpperCase(Locale.ROOT);if(!normalized.matches("[A-Z0-9_-]{3,24}")||value==null||value.signum()<=0||minimumOrder==null||minimumOrder.signum()<0||(discountType==DiscountCoupon.DiscountType.PERCENT&&value.compareTo(BigDecimal.valueOf(100))>0)||(usageLimit!=null&&usageLimit<1)||(maximumDiscount!=null&&maximumDiscount.signum()<=0)){ra.addFlashAttribute("errorMessage","Check coupon code, discount value, minimum order and usage limit.");return "redirect:/admin/coupons";}if(coupons.findByCodeIgnoreCase(normalized).isPresent()){ra.addFlashAttribute("errorMessage","That coupon code already exists.");return "redirect:/admin/coupons";}DiscountCoupon c=new DiscountCoupon();c.setCode(normalized);c.setDescription(description==null?"":description.trim());c.setDiscountType(discountType);c.setValue(value);c.setMinimumOrder(minimumOrder);c.setMaximumDiscount(maximumDiscount);c.setUsageLimit(usageLimit);c.setActive(true);c.setCreatedAt(Instant.now());coupons.save(c);ra.addFlashAttribute("successMessage","Coupon created.");return "redirect:/admin/coupons";}
 @PostMapping("/admin/coupons/{id}/toggle") public String toggle(@PathVariable String id,RedirectAttributes ra){DiscountCoupon c=coupons.findById(id).orElseThrow();c.setActive(!c.isActive());coupons.save(c);ra.addFlashAttribute("successMessage","Coupon status updated.");return "redirect:/admin/coupons";}
 @PostMapping("/coupon/apply") public String apply(@RequestParam String code,HttpSession session,RedirectAttributes ra){String normalized=code==null?"":code.trim().toUpperCase(Locale.ROOT);DiscountCoupon c=coupons.findByCodeIgnoreCase(normalized).orElse(null);if(c==null||!c.isActive()||(c.getStartsAt()!=null&&c.getStartsAt().isAfter(Instant.now()))||(c.getEndsAt()!=null&&c.getEndsAt().isBefore(Instant.now()))||(c.getUsageLimit()!=null&&c.getUsageCount()>=c.getUsageLimit())){ra.addFlashAttribute("errorMessage","Coupon is invalid, expired or no longer available.");return "redirect:/cart";}session.setAttribute("asmjCouponCode",c.getCode());ra.addFlashAttribute("successMessage","Coupon "+c.getCode()+" applied. Discount will be confirmed at checkout.");return "redirect:/cart";}
 @PostMapping("/coupon/remove") public String remove(HttpSession s){s.removeAttribute("asmjCouponCode");return "redirect:/cart";}
 public static BigDecimal discount(DiscountCoupon c,BigDecimal subtotal){if(c==null||subtotal==null||subtotal.compareTo(c.getMinimumOrder())<0)return BigDecimal.ZERO;BigDecimal amount=c.getDiscountType()==DiscountCoupon.DiscountType.PERCENT?subtotal.multiply(c.getValue()).divide(BigDecimal.valueOf(100),2,java.math.RoundingMode.HALF_UP):c.getValue();if(c.getMaximumDiscount()!=null&&c.getMaximumDiscount().signum()>0)amount=amount.min(c.getMaximumDiscount());return amount.min(subtotal).max(BigDecimal.ZERO);}
}
